<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ApiError } from '@/api/client'
import type { Edition } from '@/api/catalog'
import type { LocationTreeNode } from '@/api/locations'
import { useCollectionsStore } from '@/stores/collections'
import { useLibraryStore } from '@/stores/library'
import { useLocationsStore } from '@/stores/locations'

const route = useRoute(); const router = useRouter(); const collections = useCollectionsStore(); const library = useLibraryStore(); const locations = useLocationsStore()
const id = computed(() => Number(route.params.collectionId)); const canEdit = computed(() => ['owner','admin','editor'].includes(collections.collection?.role ?? ''))
const query = ref(''); const titleMode = ref<'existing'|'new'|null>(null); const selectedTitle = ref<number|null>(null); const editionMode = ref<'existing'|'new'|null>(null); const selectedEdition = ref<number|null>(null); const error = ref(''); const busy = ref(false)
const newTitle = ref({ display_title:'', sort_title:'', notes:'' }); const newEdition = ref({ display_name:'', media_format:'', release_date:'', publisher:'', region:'', language:'' }); const copy = ref({ condition:'', notes:'', location_id:'' })
function flatten(nodes: LocationTreeNode[], prefix=''): {id:number;path:string}[] { return nodes.flatMap(n => { const path=prefix?`${prefix} > ${n.name}`:n.name; return [{id:n.id,path},...flatten(n.children,path)] }) }
const locationOptions = computed(() => flatten(locations.tree)); const editions = computed(() => library.title?.editions ?? [])
function resetEdition(){ editionMode.value=null; selectedEdition.value=null; newEdition.value={display_name:'',media_format:'',release_date:'',publisher:'',region:'',language:''} }
function chooseExistingTitle(entryId:number){ titleMode.value='existing';selectedTitle.value=entryId;resetEdition();library.loadDetail(id.value,entryId) }
function chooseNewTitle(){ titleMode.value='new';selectedTitle.value=null;newTitle.value.display_title=query.value;resetEdition();editionMode.value='new' }
function changeTitle(){ titleMode.value=null;selectedTitle.value=null;resetEdition() }
function chooseEdition(edition:Edition){ editionMode.value='existing';selectedEdition.value=edition.id }
function message(cause:unknown){ if(cause instanceof ApiError&&cause.status===403)return 'You do not have permission to add items.'; return 'The item could not be added. Please try again.' }
async function submit(){ if(!titleMode.value||!editionMode.value)return; busy.value=true;error.value='';try{const result=await library.addItem(id.value,{title:titleMode.value==='existing'?{existing_id:selectedTitle.value,new:null}:{existing_id:null,new:{...newTitle.value,type:collections.collection?.type ?? 'movies',sort_title:newTitle.value.sort_title||null,notes:newTitle.value.notes||null}},edition:editionMode.value==='existing'?{existing_id:selectedEdition.value,new:null}:{existing_id:null,new:{...newEdition.value,media_format:newEdition.value.media_format||null,release_date:newEdition.value.release_date||null,publisher:newEdition.value.publisher||null,region:newEdition.value.region||null,language:newEdition.value.language||null}},copy:{condition:copy.value.condition||null,notes:copy.value.notes||null,location_id:Number(copy.value.location_id)||null}});await library.load(id.value);await router.push({name:'inventory-title',params:{collectionId:id.value,catalogEntryId:result.catalog_entry_id}})}catch(cause){error.value=message(cause)}finally{busy.value=false}}
let timer: ReturnType<typeof setTimeout>|undefined; watch(query, value=>{ if(timer)clearTimeout(timer); if(value.trim().length<2){library.searchResults=[];return} timer=setTimeout(()=>library.searchTitles(id.value,value).catch(()=>undefined),300) }); watch(()=>route.params.collectionId,async()=>{await collections.loadCollection(id.value);if(collections.collection)await locations.loadTree(id.value)},{immediate:true})
</script>
<template><section class="page-content workspace-content"><RouterLink class="back-link" :to="{name:'inventory',params:{collectionId:id}}">← Back to inventory</RouterLink><p class="eyebrow">Inventory</p><h1>Add item</h1><p v-if="!canEdit" class="form-error" role="alert">You do not have permission to add items.</p><form v-else class="collection-form panel" @submit.prevent="submit"><section><p class="eyebrow">Title</p><template v-if="!titleMode"><label>Title<input v-model="query" /></label><p v-if="library.error" class="form-error">Search unavailable. Try again.</p><div v-for="result in library.searchResults" :key="result.catalog_entry_id" class="selection-row"><strong>{{result.display_title}}</strong><span>{{result.edition_count}} editions · {{result.copy_count}} copies</span><button type="button" class="button-secondary" @click="chooseExistingTitle(result.catalog_entry_id)">Use existing</button></div><button v-if="query.trim()" type="button" class="button-secondary" @click="chooseNewTitle">Create new title "{{query}}"</button></template><template v-else><strong>{{titleMode==='existing'?library.title?.catalog_entry.display_title:newTitle.display_title}}</strong><button type="button" class="button-ghost" @click="changeTitle">Change</button><div v-if="titleMode==='new'"><label>Sort title <input v-model="newTitle.sort_title" /></label><label>Notes<textarea v-model="newTitle.notes" /></label></div></template></section><section v-if="titleMode"><p class="eyebrow">Edition</p><template v-if="!editionMode"><div v-for="edition in editions" :key="edition.id" class="selection-row"><strong>{{edition.display_name||'Standard Edition'}}</strong><span>{{edition.media_format}} · {{edition.copies.length}} copies</span><button type="button" class="button-secondary" @click="chooseEdition(edition)">Use this edition</button></div><p v-if="titleMode==='existing'&&!editions.length">No editions yet.</p><button type="button" class="button-secondary" @click="editionMode='new'">Create new edition</button></template><template v-else><strong>{{editionMode==='existing'?editions.find(e=>e.id===selectedEdition)?.display_name||'Standard Edition':newEdition.display_name||'New edition'}}</strong><button type="button" class="button-ghost" @click="resetEdition">Change</button><div v-if="editionMode==='new'"><label>Edition name<input v-model="newEdition.display_name" required /></label><label>Media format<input v-model="newEdition.media_format" /></label><label>Release date<input v-model="newEdition.release_date" type="date" /></label><label>Publisher<input v-model="newEdition.publisher" /></label><label>Region<input v-model="newEdition.region" /></label><label>Language<input v-model="newEdition.language" /></label></div></template></section><section v-if="editionMode"><p class="eyebrow">Physical copy</p><label>Condition<input v-model="copy.condition" /></label><label>Location<select v-model="copy.location_id"><option value="">Unassigned</option><option v-for="location in locationOptions" :key="location.id" :value="String(location.id)">{{location.path}}</option></select></label><label>Notes<textarea v-model="copy.notes" /></label><p v-if="error" class="form-error" role="alert">{{error}}</p><button :disabled="busy">{{busy?'Adding…':'Add item'}}</button></section></form></section></template>
